//! Differential test for `GetMostSuitableMonToSwitchInto`. The checked-in
//! cases were generated by executing canonical TypeScript's
//! `getMostSuitableMonToSwitchInto`; regenerate with
//! `node --experimental-strip-types core-rs/tools/gen-battle-ai-switch-into-vectors.mjs`.

use factory_core::battle_ai_switch_into::{
    get_most_suitable_mon_to_switch_into, BattleAiSwitchBench, BattleAiSwitchBenchMember,
    BattleAiSwitchDamageFallback, BattleAiSwitchIntoResult,
};
use factory_core::battle_ai_switch_into_vectors_gen::{
    BattleAiSwitchBenchMemberCase, BattleAiSwitchDamageFallbackCase, BATTLE_AI_SWITCH_INTO_CASES,
};

fn member(case: BattleAiSwitchBenchMemberCase) -> BattleAiSwitchBenchMember {
    BattleAiSwitchBenchMember {
        species: case.species,
        hp: case.hp,
        types: case.types,
        moves: case.moves,
    }
}

fn fallback(case: BattleAiSwitchDamageFallbackCase) -> BattleAiSwitchDamageFallback {
    BattleAiSwitchDamageFallback {
        base_damage: case.base_damage,
        active_types: case.active_types,
        opposing_types: case.opposing_types,
        opposing_ability: case.opposing_ability,
        opposing_status2: case.opposing_status2,
    }
}

#[test]
fn cases_match_canonical_typescript() {
    assert!(BATTLE_AI_SWITCH_INTO_CASES.len() >= 200);
    for (index, case) in BATTLE_AI_SWITCH_INTO_CASES.iter().enumerate() {
        let bench = case.bench.map(member) as BattleAiSwitchBench;
        let actual = get_most_suitable_mon_to_switch_into(
            &bench,
            case.active_party_index,
            case.opposing_types,
            case.has_damage_fallback.then(|| fallback(case.fallback)),
        );
        match (case.expected_kind, actual) {
            (0, BattleAiSwitchIntoResult::Resolved { party_index }) => assert_eq!(
                party_index, case.expected_party_index,
                "case {index} ({})",
                case.label,
            ),
            (1, BattleAiSwitchIntoResult::DamageFallbackNeeded) => {}
            (expected_kind, actual) => panic!(
                "case {index} ({}) expected kind {expected_kind}, got {actual:?}",
                case.label,
            ),
        }
    }
}
